#include <bits/stdc++.h>
using namespace std;
struct Q{string op,a,b,res;};
struct Gen{string s;size_t p=0;int temp=1;vector<Q> q;void ws(){while(p<s.size()&&isspace((unsigned char)s[p]))++p;}string atom(){ws();if(p<s.size()&&s[p]=='('){++p;string x=expr();ws();if(p<s.size()&&s[p]==')')++p;else throw runtime_error("missing )");return x;}size_t st=p;while(p<s.size()&&(isalnum((unsigned char)s[p])||s[p]=='_'||s[p]=='.'))++p;if(st==p)throw runtime_error("expected operand");return s.substr(st,p-st);}string term(){string a=atom();while(true){ws();if(p<s.size()&&(s[p]=='*'||s[p]=='/')){char op=s[p++];string b=atom(),t="t"+to_string(temp++);q.push_back({string(1,op),a,b,t});a=t;}else break;}return a;}string expr(){string a=term();while(true){ws();if(p<s.size()&&(s[p]=='+'||s[p]=='-')){char op=s[p++];string b=term(),t="t"+to_string(temp++);q.push_back({string(1,op),a,b,t});a=t;}else break;}return a;}};
int main(){string line;getline(cin,line);auto k=line.find('=');if(k==string::npos){cout<<"Enter assignment like a=b+c*d\n";return 1;}string lhs=line.substr(0,k);lhs.erase(remove_if(lhs.begin(),lhs.end(),[](char c){return isspace((unsigned char)c);}),lhs.end());try{Gen g;g.s=line.substr(k+1);string result=g.expr();g.ws();if(g.p!=g.s.size())throw runtime_error("unexpected input");g.q.push_back({"=",result,"-",lhs});cout<<"Three Address Code\n";for(auto &x:g.q)cout<<x.res<<" = "<<x.a<<' '<<(x.op=="="?"":x.op)<<' '<<(x.op=="="?"":x.b)<<'\n';cout<<"\nQuadruples\nIndex  Op  Arg1  Arg2  Result\n";for(int i=0;i<(int)g.q.size();i++){auto x=g.q[i];cout<<i<<"      "<<x.op<<"   "<<x.a<<"   "<<x.b<<"   "<<x.res<<'\n';}cout<<"\nTriples\nIndex  Op  Arg1  Arg2\n";for(int i=0;i<(int)g.q.size();i++){auto x=g.q[i];string a=x.a,b=x.b;for(int j=0;j<i;j++)if(g.q[j].res==a)a="("+to_string(j)+")";for(int j=0;j<i;j++)if(g.q[j].res==b)b="("+to_string(j)+")";cout<<i<<"      "<<x.op<<"   "<<a<<"   "<<b<<'\n';}}catch(exception&e){cerr<<"Parse error: "<<e.what()<<'\n';return 1;}}
